#!/usr/bin/env python3
"""Build the versioned proposal for producers; no approval state is inferred."""
from pathlib import Path
import html,json,hashlib
import tais_package_example as example
R=Path(__file__).resolve().parents[1];D=R/'Production/Dashboard';O=R/'docs/World/characters/final-package';O.mkdir(parents=True,exist_ok=True)
p=json.loads((D/'Character_Package_Proposal_2026-11-17.json').read_text());e=html.escape
exclusions=['Измерение особенностей телосложения, сравнения с другими персонажами, высота сидя и досягаемость рук.','Отдельные карты захватов предметов и их поведения в движении; избыточная детализация стоп.','Самостоятельный блок материалов, палитры и контрольного света.','Сцены взаимодействия с другими героями.','Дополнение для роботов — пока отложено.']
md_items=['ID персонажа, код выбранной внешности и ссылки на эталоны.','Постоянные признаки образа, которые нужно сохранять.','Промпты для каждого типа листа из этого пакета и необходимые входные референсы.','Коды костюмов и сюжетных состояний.','Отдельные стилевые блоки для фотореализма и двух анимационных версий выбранного ядра.','Проверенные параметры генерации, если они влияют на результат.','Краткая проверка: сходство, возраст, пропорции, анатомия, асимметрия, нужный костюм и состояние.']
md=f'# {p["title"]}\n\nВерсия {p["version"]} · 17 ноября 2026 · Предложение на согласование\n\n{p["purpose"]}\n\nОбласть: {p["scope"]}\n\n'
nav='';body='';last=''
for s in p['sections']:
 if s['group']!=last:
  if last:body+='</section>'
  last=s['group'];body+=f'<section class="package-chapter" aria-label="{e(last)}"><h2 class="package-chapter-title">{e(last)}</h2>'
 nav+=f'<a href="#p-{s["id"]}"><span class="mono">{s["code"]}</span>{e(s["title"])}</a>'
 body+=f'<article class="package-item" id="p-{s["id"]}"><a class="package-code mono" href="#p-{s["id"]}" aria-label="Ссылка на раздел {s["code"]}">{s["code"]}</a><div><h3>{e(s["title"])}</h3><p class="package-lead">{e(s["lead"])}</p><ul>'+''.join('<li>'+e(a)+'</li>' for a in s['items'])+'</ul>'
 if s['id']=='continuity':body+='<div class="package-table-wrap"><table><caption>Структура карты изменений</caption><thead><tr><th>Событие / страницы</th><th>Костюм</th><th>Волосы / лицо</th><th>Травмы</th><th>Вещи</th></tr></thead><tbody><tr><td>Эпизод романа</td><td>Код комплекта</td><td>Код состояния</td><td>Сторона тела</td><td>Код предмета</td></tr></tbody></table></div>'
 body+=example.section_example(s['id'])
 body+='</div></article>'
 md+='## '+s['code']+' · '+s['title']+'\n\n'+s['lead']+'\n\n'+''.join('- '+a+'\n' for a in s['items'])+'\n'
body+='</section>'
md+='## Формат финальной сдачи\n\n1. Сводный PDF с навигацией, всеми листами, картой изменений и примечаниями по источникам.\n2. Отдельные изображения в полном качестве для использования как референсов.\n3. MD-файл с пакетом промптов для агентов.\n\n### Содержание MD-файла\n\n'+''.join('- '+a+'\n' for a in md_items)+'\n## Не входит в текущий состав\n\n'+''.join('- '+a+'\n' for a in exclusions)+'\nКоличество костюмов, предметов и состояний определяется романом для каждого героя. Рост и пропорции можно объединить с character sheet; 13 разделов не означают 13 обязательных отдельных файлов.\n\n## Предмет согласования\n\nУтверждается состав пакета персонажа для третьего этапа, включая две анимационные версии выбранного ядра. Материалы конкретных персонажей принимаются отдельно. Раздел роботов в эту версию не входит. Ориентиры 12–16 выражений и 8–12 поз относятся к основным героям, не являются обязательной нормой для каждого эпизодического персонажа.\n\nРешение: '+p['tracker']['url']+'\n'
(D/'Character_Package_Proposal_2026-11-17.md').write_text(md);(O/'proposal-v1.md').write_text(md)
formats='''<section class="package-delivery" id="delivery"><h2>Что сдаём</h2><div class="package-file"><span class="mono">PDF</span><div><h3>Сводный паспорт</h3><p>Навигация, все листы, карта изменений и примечания по источникам.</p></div></div><div class="package-file"><span class="mono">IMG</span><div><h3>Отдельные изображения</h3><p>Полное качество, чтобы каждый лист можно было использовать как самостоятельный референс.</p></div></div><div class="package-file"><span class="mono">MD</span><div><h3>Промпты для агентов</h3><p>Воспроизводимый набор описаний и референсов для продолжения работы.</p></div></div><details class="package-details"><summary>Что должно быть в MD-файле</summary><ul>'''+''.join('<li>'+e(a)+'</li>' for a in md_items)+'''</ul></details></section>'''
excluded='<section class="package-excluded" id="scope"><h2>Уточнённый объём</h2><p>Количество костюмов, предметов и состояний определяется историей конкретного героя. Рост и пропорции можно объединить с character sheet. Разделы — состав пакета, а не фиксированное количество отдельных листов.</p><details class="package-details"><summary>Что исключили из этой версии</summary><ul>'+''.join('<li>'+e(a)+'</li>' for a in exclusions)+'</ul></details></section>'
version=lambda n:hashlib.sha256((O/n).read_bytes()).hexdigest()[:12]
page=f'''<link rel="stylesheet" href="package.css?v={version('package.css')}"><div class="package-proposal"><header class="package-heading"><h1>Финальный пакет<br>персонажа</h1><p class="package-meta">Предложение состава · версия 1.0 · 17 ноября 2026</p><p class="package-intro">Что передаём по каждому герою в конце третьего этапа: от выбранного образа и мимики до одежды, личных вещей и карты изменений по роману.</p><div class="package-actions"><a class="button primary-button" href="{p['tracker']['url']}">Согласовать состав в трекере ↗</a><a class="quiet-link" href="#comments">Оставить комментарий ↓</a><a class="quiet-link" href="proposal-v1.md" download>Скачать предложение · MD</a></div></header><div class="package-decision"><strong>Предмет согласования</strong><p>Состав будущей сдачи для персонажей. Принятие этой версии не означает готовность отдельных героев. Дополнение для роботов отложено; две анимационные версии готовятся для выбранного ядра.</p></div>{example.intro()}<div class="package-layout"><aside class="package-index"><details open id="package-index"><summary>Содержание</summary><nav aria-label="Разделы предложения">{nav}<a href="#delivery">Формат сдачи</a><a href="#scope">Уточнённый объём</a></nav></details><p>Для замечания укажите код раздела, например <span class="mono">P04</span>.</p></aside><div class="package-content">{body}{formats}{example.downloads()}{excluded}<section class="package-review" id="review"><h2>Обсудить и согласовать</h2><p>Замечания к составу можно оставить ниже или в карточке трекера. Решения Лены и Игоря относятся к конкретной версии предложения.</p><div class="package-actions"><a class="button primary-button" href="{p['tracker']['url']}">Открыть карточку согласования ↗</a><a class="quiet-link" href="#comments">К комментариям ↓</a></div><p class="package-small">Организация будущей сдачи: <a href="https://gingers.media/alive/plan/#w=KPP-R357">финальные комплекты</a> · <a href="https://gingers.media/alive/plan/#w=KPP-R329">костюмы и личные вещи</a>.</p></section></div></div></div>{example.dialog()}<script defer src="package.js?v={version('package.js')}"></script>'''
(D/'character_package_body.html').write_text(page)
x=json.load(open(D/'objects.json'));record=dict(id='character-final-package',title='Финальный пакет персонажа',path='characters/final-package',group='people',task_ids=['character-concepts','costume','acting','states'],summary='Состав пакета · 23 листа на примере Таис',image='characters/final-package/cover.svg',body_file='Production/Dashboard/character_package_body.html',label='Для продюсеров',button_label='Прочитать предложение')
x['studies']=[s for s in x['studies'] if s['id']!=record['id']];x['studies'].insert(0,record);(D/'objects.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
print('Built version 1.0 proposal: 13 sections, delivery formats, scope, tracker links')
